/// What served a local dep-file cache lookup. Distinguishes a hit from the
/// in-memory map, which costs nothing, from one reloaded off disk, which costs
/// the queries measured below.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum DepFileLookupOutcome {
    NotSet = 0,
    /// Nothing served the lookup; the action goes on to execute.
    Miss = 1,
    /// Served from the in-memory cache, i.e. built earlier in this daemon session.
    Live = 2,
    /// Served from the persisted store, i.e. built by an earlier daemon.
    Persisted = 3,
    /// The lookup failed. Distinct from a miss: the action does not go on to
    /// execute, it fails, so counting these as misses would understate the hit
    /// rate against a denominator that includes actions that never ran.
    Error = 4,
}
